interface KeyProps {
  primary: string;
  secondary?: string;
  isWide?: boolean;
  isHighlighted?: boolean;
  className?: string;
}

const Key: React.FC<KeyProps> = ({ primary, secondary, isWide, isHighlighted, className = "" }) => {
  const baseClasses = "box-border relative bg-white rounded-lg border border-solid shadow-sm border-zinc-100 text-zinc-500";
  const highlightedClasses = isHighlighted ? "bg-blue-600 bg-opacity-60 text-white" : "";
  const sizeClasses = isWide 
    ? "h-[62px] w-[95px] max-md:h-[50px] max-md:w-auto max-md:min-w-[60px] max-sm:w-10 max-sm:h-10"
    : "h-[62px] w-[62px] max-md:h-[50px] max-md:w-[50px] max-sm:w-10 max-sm:h-10";
  
  if (secondary) {
    const textColor = isHighlighted ? "text-white" : "text-zinc-500";
    return (
      <div className={`${baseClasses} ${highlightedClasses} ${sizeClasses} flex flex-col gap-3 justify-center items-center px-0 pt-2.5 pb-1.5 text-sm max-md:gap-2 max-md:px-0 max-md:pt-2 max-md:pb-1 max-md:text-xs max-sm:gap-1 max-sm:px-0 max-sm:pt-1.5 max-sm:pb-0.5 max-sm:text-xs ${className}`}>
        <div className={`text-sm ${textColor} max-md:text-xs max-sm:text-xs`}>{primary}</div>
        <div className={`text-sm ${textColor} max-md:text-xs max-sm:text-xs`}>{secondary}</div>
      </div>
    );
  }

  if (isWide) {
    return (
      <div className={`${baseClasses} ${sizeClasses} text-xs pt-10 pr-2 pb-2 pl-2 max-md:px-2 max-md:py-5 max-md:text-xs max-sm:px-1.5 max-sm:py-4 max-sm:text-xs ${className}`}>
        {primary}
      </div>
    );
  }

  return (
    <div className={`${baseClasses} ${sizeClasses} text-sm max-md:text-xs max-sm:text-xs flex items-center justify-center ${className}`}>
      {primary}
    </div>
  );
};

